// «Monitoring турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

// Нэг агшны үсрэлт — сэрэмжлүүлэх ёсгүй.
const spike = [10, 12, 95, 11, 13];
// Тогтвортой өндөр — сэрэмжлүүлэх ёстой.
const sustained = [12, 85, 90, 93, 91];

window.ALERT_SPIKE = null;
window.ALERT_SUSTAINED = null;
try {
  window.ALERT_SPIKE = shouldAlert(spike, 80, 3);
  window.ALERT_SUSTAINED = shouldAlert(sustained, 80, 3);
  panel(!window.ALERT_SPIKE ? "ok" : "bad", "spike", "Нэг агшны үсрэлт", ["shouldAlert → " + window.ALERT_SPIKE]);
  panel(window.ALERT_SUSTAINED ? "ok" : "bad", "sustained", "Тогтвортой өндөр", ["shouldAlert → " + window.ALERT_SUSTAINED]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}
document.body.dataset.ready = "1";

